def removeDuplicates(s: str, k: int) -> str:
    # Each item on the stack: (char, current consecutive count)
    stack = []

    for c in s:
        if stack and stack[-1][0] == c:
            stack[-1][1] += 1
            # If k of the same char: remove them
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([c, 1])

    # Rebuild result from stack
    result = ""
    for char, count in stack:
        result += char * count
    return result
